using System;using System.Text;using UnityEngine;using DigitalRuby.WeatherMaker;using LWS.TruckSports;using LWS.TruckBowling;
namespace LWS.TruckBogSnorkelling {
public enum BogPhase{Countdown,Racing,RaceResult,Complete}
public sealed class BogMatch:SportsEventSession {
 public override bool SupportsRaceCountdown=>true;public override float RaceCountdownSeconds=>Phase==BogPhase.Countdown?Mathf.Max(0,3-Age):-1;public override float RaceStartSeconds=>Phase==BogPhase.Racing?Clock:-1;
 public BogRacer[] racers;public BogCourse course;public SportsRallyViews views;public BogCameraEffects[] effects;public WeatherMakerFullScreenFogScript fog;public TextMesh[] identities;public SportsRaceSeries series=new SportsRaceSeries();public BogPhase Phase{get;private set;}public float Clock{get;private set;}public int Seed{get;private set;}public float Age{get;private set;}
 readonly float[] times=new float[4],think=new float[4];readonly Vector2[] ai=new Vector2[4];readonly bool[] diveAI=new bool[4];readonly Quaternion[] headings={Quaternion.identity,Quaternion.identity,Quaternion.identity,Quaternion.identity};readonly Vector3[] offsets=new Vector3[4];readonly StringBuilder text=new StringBuilder(1400);int focus;
 protected override void Awake(){base.Awake();if(fog!=null&&fog.FogProfile!=null){fog.FogProfile=Instantiate(fog.FogProfile);fog.FogProfile.name="Bog runtime weather fog clone";}}
 public override string Title=>"TRUCK BOG SNORKELLING";public override int MinimumPlayers=>4;public override int MaximumPlayers=>4;public override int OptionCount=>2;public override int WeatherCount=>3;public override string OptionLabel=>option==1?"HARD · FLOODED GALLERIES · 650m":"CLASSIC BOG · 350m";public override bool MultiViewHUD=>views!=null&&views.Humans>0;
 public override string Help=>"HARD COURSE · FLOODED GALLERIES\nThe additional650m course has six75–80m submerged stone galleries and short open-air recovery pockets. Your snorkel cannot breathe through a solid roof. A committed fast line fits the14-second air supply; dawdling underwater risks a real stall. Release dive and rise in marked open-air pockets, refill, then enter the next gallery. Classic350m remains unchanged.\n\nBREATHE, DIVE, DRIVE\nFour snorkel-equipped trucks race three flooded muddy courses. Up to four local humans; AI fills missing slots. MOVE drives, steers, brakes and reverses. HOLD ACTION to DIVE: bounded downward force reduces buoyancy so your tyres grip the trench bottom and fit under marked logs. Release to rise; a gentle bounded paddle force preserves manoeuvrability while floating. Every truck uses the same NWH tyres, water drag, buoyancy and air limits.\n\nARCADE AIR\nYour real snorkel intake must be ABOVE the actual water surface and unobstructed to replenish air. Otherwise a14-second gauge drains. Surfacing pockets between short submerged sections restore4seconds of air per second. Follow markers, dive under low trunks, then surface; a longer shallow branch on the right avoids the middle deep shortcut. Rain changes shared surface grip; water depth stays fixed.\n\nFAILURE IS RECOVERABLE\nAt empty air, the engine sputters and stalls for2s, then returns to the LAST VALID SAFE checkpoint, never forward, with a5-second penalty. Genuine stranding has the same recovery. More than three recoveries or a240s race cap is DNF. Other racers continue independently. Ordered flags prevent shortcuts; the whole course must be traversed.\n\nThree races,4/3/2/1 placement points; DNF zero. Highest cumulative total wins; tied leaders run an extra race. Rematch retains names/colors/input and difficulty. Per-human stable chase views follow below the water with hysteresis, camera-local depth fog/refraction and readable route markers. Bubbles, sediment, snorkels and headlamps show real depth; no global blue screen. One listener; each submerged truck engine is filtered separately. Pause/disconnect preserves all bodies, air, score and clock. Offline only.";
 public override string Header=>Title+" | "+(series.round>3?"TIEBREAK":"RACE "+series.round+" / 3")+" | "+(weather==0?"CLEAR":weather==1?"RAIN":"FOG");public override string Status=>Phase==BogPhase.Countdown?Mathf.CeilToInt(3-Age).ToString():Phase==BogPhase.Racing?"HOLD ACTION TO DIVE · RELEASE TO SURFACE · "+Clock.ToString("F1")+"s":"RACE PLACEMENTS LOCKED";
 public override string Standings{get{text.Clear();for(int i=0;i<4;i++)text.Append(setup.players[i].name).Append("  ").Append(series.total[i]).Append(" PTS · ").Append(racers[i].Checkpoint).Append("/").Append(course.checkpoints.Length).Append(" · AIR ").Append(racers[i].Air.ToString("F0")).Append("s").Append(i==3?"":"\n");return text.ToString();}}public int ResultPlace(int slot)=>SportsResultPlacings.FromFinalTotals(slot,setup.count,series.total,series.winner);
 public override string Results=>(series.winner>=0?setup.players[series.winner].name+" WINS":"TIED")+"\n\n"+Standings;
 protected override void BeginGame(){Seed=UnityEngine.Random.Range(1,100000);series.Reset(4,false);BeginRace();}
 void BeginRace(){course.SelectCourse(option==1);series.BeginRound();Clock=Age=0;Phase=BogPhase.Countdown;focus=0;course.weather.Configure(Seed+series.round*313,weather==1?2:1,0);if(fog!=null&&fog.FogProfile!=null){fog.UseUnityFog=false;fog.FogProfile.FogDensity=weather==2?.018f:0;fog.FogProfile.FogColor=new Color(.59f,.66f,.61f);}for(int i=0;i<4;i++){think[i]=0;times[i]=float.PositiveInfinity;racers[i].Prepare((series.eligible&(1<<i))!=0);headings[i]=Quaternion.identity;offsets[i]=new Vector3(0,3.4f,-9);}views.Layout();Gate();}
 Vector2 AI(int i){if(Clock<think[i])return ai[i];float difficulty=(int)setup.players[i].difficulty;think[i]=Clock+Mathf.Lerp(.3f,.1f,difficulty*.5f);var r=racers[i];var p=r.truck.body.position;float z=Mathf.Min(course.FinishDistance+7,p.z+9);bool longer=!course.Hard&&p.z>135&&p.z<197&&(difficulty==0||difficulty==1&&i%2==0);float x=BogCourse.Center(z)+(longer?16:(i-1.5f)*5);x+=Mathf.Sin(p.z*.06f+i)*Mathf.Lerp(.9f,.1f,difficulty*.5f);var target=course.Surface(new Vector3(x,0,z));float angle=Vector3.SignedAngle(Vector3.ProjectOnPlane(r.truck.transform.forward,Vector3.up),Vector3.ProjectOnPlane(target-p,Vector3.up),Vector3.up);float desired=course.Safe(p.z)&&r.Air<10?1.5f:course.MustDive(p)?course.Hard?7.4f:5.5f:course.Hard?8:6.5f;float speed=Vector3.Dot(r.truck.body.linearVelocity,r.truck.transform.forward);ai[i]=new Vector2(Mathf.Clamp(angle/28,-1,1),Mathf.Clamp((desired-speed)*.6f,-1,1));diveAI[i]=course.MustDive(p)||!course.Safe(p.z)&&r.Air>9&&difficulty>0;return ai[i];}
 protected override void Simulate(float dt){Age+=dt;if(Phase==BogPhase.Countdown){if(Age>=3){Phase=BogPhase.Racing;Age=0;foreach(var r in racers)r.Release();}return;}if(Phase==BogPhase.RaceResult){if(Age>5){if(series.winner>=0){Phase=BogPhase.Complete;EndMatch();}else BeginRace();}return;}if(Phase!=BogPhase.Racing)return;Clock+=dt;course.weather.Tick(Clock);int resolved=0;float lead=-999;for(int i=0;i<4;i++){bool bot=setup.players[i].source==BowlingSource.AI;var command=bot?AI(i):commands[i];racers[i].Step(command,bot?diveAI[i]:setup.players[i].released&&ActionHeld(i),dt);if(racers[i].State==BogState.Finished||racers[i].State==BogState.DNF||racers[i].State==BogState.Inactive)resolved++;else if(racers[i].truck.body.position.z>lead){lead=racers[i].truck.body.position.z;focus=i;}}if(Clock>240){foreach(var r in racers)r.Fail();resolved=4;}if(resolved==4){for(int i=0;i<4;i++)times[i]=racers[i].FinishTime;if(series.Resolve(times)){Phase=BogPhase.RaceResult;Age=0;feedback.Play(5,0,true);Gate();Debug.Log("BOG_RACE_LOCK round="+series.round+" times="+string.Join(",",times)+" points="+string.Join(",",series.total));}}}
 public override string ViewText(int view){int i=views.owners[view];var r=racers[i];return "<color=#"+ColorUtility.ToHtmlStringRGB(setup.players[i].color)+">"+setup.players[i].name+"</color> · "+series.total[i]+" PTS · RACE "+series.round+"\nAIR "+r.Air.ToString("F1")+" / 14s · FLAGS "+r.Checkpoint+"/"+course.checkpoints.Length+"\n"+(r.State==BogState.Penalty?"RECOVERY +5s · "+r.PenaltyRemaining.ToString("F1"):r.State==BogState.Stalled?"AIR EMPTY · ENGINE STALLED":r.State==BogState.Finished?"FINISHED · "+r.FinishTime.ToString("F1")+"s":r.State==BogState.DNF?"DNF · WATCHING LEADER":r.Submerged?r.Air<4?"LOW AIR! RELEASE ACTION TO SURFACE":"SUBMERGED · HOLD ACTION UNDER LOGS":r.IntakeOpen?"INTAKE CLEAR · AIR REFILLING":"INTAKE BLOCKED");}
 protected override void Present(float dt){if(racers==null||views==null)return;for(int i=0;i<4;i++){racers[i].Effects();identities[i].gameObject.SetActive(racers[i].State!=BogState.Inactive);identities[i].transform.position=racers[i].truck.body.position+Vector3.up*2.4f;identities[i].text=setup.players[i].name;identities[i].color=setup.players[i].color;}int count=views.Humans==0?1:views.Humans;for(int v=0;v<count;v++){int i=views.Humans==0?focus:views.owners[v];if(racers[i].State==BogState.DNF||racers[i].State==BogState.Inactive)i=focus;var t=racers[i].truck;var forward=Vector3.ProjectOnPlane(t.transform.forward,Vector3.up);if(forward.sqrMagnitude>.1f&&Vector3.Dot(t.transform.up,Vector3.up)>.4f)headings[v]=Quaternion.Slerp(headings[v],Quaternion.LookRotation(forward),1-Mathf.Exp(-dt*3));offsets[v]=Vector3.Lerp(offsets[v],racers[i].Submerged?new Vector3(0,1.3f,-7.5f):new Vector3(0,3.4f,-9),1-Mathf.Exp(-dt*2));var rig=views.Humans==0?views.broadcast:views.views[v];rig.Pose(t.body.position+Vector3.up*.6f+headings[v]*Vector3.forward*3,headings[v]*offsets[v],70);}}
 protected override void SetPaused(bool paused)=>course?.weather?.Pause(paused);protected override void StopGame(){if(racers!=null)foreach(var r in racers){r.ClearEffects();r.truck.Park(r.truck.body.position);}}protected override void StopSounds(){if(racers!=null)foreach(var r in racers)r.truck.StopSound();}
}
}
